function collaborationScene(){return `<section class="collab-scene"><span class="eyebrow">D2 Batch B · SRC-015 · ${L('Approved demo design','已批准演示设计')}</span><h3>${L('From a requirement to a reviewed response','从要求到经复核的响应')}</h3><div class="collab-route"><span>${L('Requirements / purpose','要求 / 用途')}</span> → <span>${L('Two residual items','两个残余项目')}</span> → <span>${L('Limited contribution','有限范围贡献')}</span> → <span>${L('Purpose review','用途复核')}</span></div><p>${L('Person T provides the authority item for Entity A. Ownership remains a separate item. Access, submission and purpose sufficiency are separate states; the case remains not ready.','Person T 提供针对 Entity A 的权限项目资料；ownership 保留为独立项目。访问、提交和用途充分性分别记录；案件仍未就绪。')}</p><details><summary>${L('Request / submission / assessment relationship','请求 / 提交 / 评估关系')}</summary><img class="collab-diagram" src="./diagrams/batch-b/client-collaboration.${n.locale}.svg" alt="${L('Requirement creates scoped request; limited contributor submits one item; Ops assesses its purpose; other conditions remain.','要求形成限定请求；贡献者提交一个项目；Ops 按用途评估；其他条件保持未决。')}"></details>${button(L('Open client collaboration','打开客户协作'),'collab-open','','primary')}</section>`;}
