async function startSpecialists(){
 if(dLoadPending||isDSession())return;
 const prior={data:structuredClone(data),drafts:structuredClone(drafts),navigation:structuredClone(n),collabCtx:structuredClone(collabCtx),cRationale};
 dLoadPending=true;error='';render();
 try{
  const payload=await fetch('../04_operating_model/batch-d/specialist-snapshots.json').then(r=>{if(!r.ok)throw Error('D_SNAPSHOT_UNAVAILABLE');return r.json();});
  const next=structuredClone(payload.snapshots?.['D-entry']);
  if(!next||createBatchD(next)!==next)throw Error('D_SNAPSHOT_INVALID');
  archives.push({kind:'pre-batch-d',...prior,archived_at:new Date().toISOString()});
  versions.push(structuredClone(prior.data));data=next;n.role='ROLE-FACILITATOR';n.conditionDomain=({'SCN-CONFLICTS':'conflicts','SCN-CREDIT':'credit','SCN-LEGAL':'legal'})[n.scenario]||'conflicts';
  const p=dProjection();n.agreementRevision=p.legal?.agreement_revision;n.liveAgreementRevision=p.legal?.agreement_revision;n.liveCaseRevision=p.revision;n.dGraph={graph:n.dGraph?.graph||'DG-D01',focus:null,cursor:0,playing:false};
  dSavedRationale='';dRationale='';dDirty=false;dirty=false;cDirty=false;error='';message='';
 }catch(e){error=`${L('The authored D entry could not be loaded.','无法载入编制的 D 入口。')} [${esc(e.code||e.message)}]`;}
 finally{dLoadPending=false;persist();render();}
}
function restorePreD(){
 const archived=[...archives].reverse().find(x=>x.kind==='pre-batch-d');if(!archived){error=L('No archived pre-D session is available.','没有可恢复的 D 前归档会话。');render();return;}
 const locale=n.locale;versions.push(structuredClone(data));data=structuredClone(archived.data);drafts=structuredClone(archived.drafts||{});n={...structuredClone(archived.navigation||initialNavigation()),locale};collabCtx=structuredClone(archived.collabCtx||{audience:'ops',tab:'requirements',userId:null,sessionId:null,itemId:null});cRationale=archived.cRationale||'';
 dSavedRationale='';dRationale='';dDirty=false;dirty=false;cDirty=false;stopD();error='';message=L('Archived pre-D session restored. Batch C actions are available in their original state.','已恢复 D 前归档会话；Batch C 操作按原状态恢复可用。');persist();render();
}
function specialistErrorText(e){const code=e.code||e.message,map={D_RATIONALE_REQUIRED:L('Enter a rationale for this facilitator simulation.','请输入主持人模拟理由。'),D_STALE_CASE:L('Case revision changed. Review the current specialist state before retrying.','案件版本已变化；请复核当前专业条线状态后重试。'),D_STALE_SCOPE:L('Scope revision changed. Review the current specialist state before retrying.','范围版本已变化；请复核当前专业条线状态后重试。'),D_STALE_INPUT:L('A specialist input changed. Review the version chain before retrying.','专业条线输入已变化；请复核版本链后重试。'),D_PERMISSION_REQUIRED:L('Only the configured facilitator can run this revision simulation.','仅已配置的主持人可运行此修订模拟。')};return `${map[code]||L('The specialist simulation is unavailable under the current input, permission or Hold.','由于当前输入、权限或 Hold，专业条线模拟不可用。')} [${esc(code)}]`;}
function submitSpecialist(){
 try{const p=dProjection();const before=data,next=specialistAction(data,{type:'revise_credit',role:n.role,expectedRevision:data.case.revision,expectedScopeRevision:data.scopes[0].revision,expectedInputRevisions:p.inputRevisions,key:`D:revise_credit:${data.case.revision}:${crypto.randomUUID()}`,rationale:dRationale,at:new Date().toISOString()});if(next!==data){versions.push(before);data=next;}const updated=dProjection();n=navigate(n,{type:'D_DATA_REVISION',caseRevision:updated.revision,agreementRevision:updated.legal?.agreement_revision});dSavedRationale='';dRationale='';dDirty=false;error='';message=L('Synthetic Credit input revised. AGR-01 revision 03 is frozen and now flags its superseded input; no approval or execution occurred.','合成信贷输入已修订。AGR-01 版本 03 保持冻结并标记旧输入；未发生批准或签署。');persist();render();}
 catch(e){error=specialistErrorText(e);render();}
}
function scheduleSpecialistPlayback(){clearTimeout(dTimer);if(!n.dGraph?.playing)return;dTimer=setTimeout(()=>{n.dGraph=specialistGraphState(n.dGraph,{type:'NEXT'});render();scheduleSpecialistPlayback();},1800);}
function screeningErrorText(e){const code=e.code||e.message;const map={B_CONTEXT_REQUIRED:L('A current Batch B collaboration context is required.','需要当前 Batch B 协作上下文。'),RATIONALE_REQUIRED:L('Enter a rationale; the draft has been retained.','请输入理由；草稿已保留。'),DRAFT_TEXT_REQUIRED:L('Enter review text; the draft has been retained.','请输入复核文本；草稿已保留。'),CASE_VERSION_CONFLICT:L('Case version changed. Review the current inputs; your draft is retained.','案件版本已变化。请复核当前输入；草稿已保留。'),SCOPE_VERSION_CONFLICT:L('Scope version changed. Review the current inputs; your draft is retained.','范围版本已变化。请复核当前输入；草稿已保留。'),INPUT_VERSION_CONFLICT:L('One or more prepared inputs changed. Refresh only after reviewing them; your draft is retained.','一个或多个已准备输入发生变化。请复核后刷新；草稿已保留。'),EXCLUSION_DISABLED_PENDING_FIXTURE_REVIEW:L('Exclusion is disabled pending reviewed fixture and permission configuration.','排除结论等待经复核的样例及权限配置。')};return `${map[code]||L('Action unavailable under the current permission, input or Hold.','由于当前权限、输入或 Hold，本操作不可用。')} [${esc(code)}]`;}
function collaborationError(e){const raw=e.message;return n.locale!=='zh-CN'?raw:L(raw,/revision|stale|scope/i.test(raw)?'记录版本或范围已变化。输入已保留，请重新检查后再提交。':/permission|grant|recipient|session|auth/i.test(raw)?'此模拟身份或访问范围不允许本操作。输入已保留；请检查会话、访问授权与收件人。':/rationale|text|draft|length|response/i.test(raw)?'请提供有效的合成响应或理由。输入已保留，请检查内容与长度。':/release|quarantine|intake|link/i.test(raw)?'资料尚未获准进入本用途评估，请检查模拟接收状态与证据关联。':'操作未完成。请检查请求审阅、渠道配置及所需输入。')+' ['+raw+']';}
function submitCollab(type,draw=true,itemId){
 try{
  if(!data.demoConfig.batchB)throw Error('Open Batch B first');
  const p=collabProjection(),item=p.items?.find(x=>x.id===(itemId||collabCtx.itemId))||p.items?.[0];
  const isDraft=['save_request','save_response','submit_response'].includes(type),role=collabCtx.audience==='client'?'ROLE-CLIENT':collabCtx.audience==='rm'?'ROLE-RM':'ROLE-KYCOPS';
  const artifact=data.evidence.filter(x=>x.request_item_refs?.includes(item?.id)).at(-1);
  const submissionIdentity=JSON.stringify([collabCtx.userId||COLLAB_IDS.personT,item?.id,draft]);
  if(type==='submit_response'&&collabCtx.submissionIdentity!==submissionIdentity){collabCtx.submissionIdentity=submissionIdentity;collabCtx.submissionKey=crypto.randomUUID();}
  const identity=collabCtx.requestId===C_IDS.request;
const next=collaborationAction(data,{type,role,requestId:collabCtx.requestId,expectedRevision:isDraft?collabEdit.caseRevision:data.case.revision,expectedRequestRevision:isDraft?collabEdit.requestRevision:p.request_revision,expectedItemRevision:isDraft?collabEdit.itemRevision:item?.revision,itemId:item?.id,userId:collabCtx.userId||COLLAB_IDS.personT,sessionId:type==='start_session'?crypto.randomUUID():collabCtx.sessionId,recipientId:identity?C_IDS.recipientT:(collabCtx.userId||COLLAB_IDS.personT)===COLLAB_IDS.personT?COLLAB_IDS.recipientT:COLLAB_IDS.recipientOther,reference:['release_artifact','link_evidence','record_assessment'].includes(type)?artifact?.id:identity?'CTT-DEMO-ID-C01':data.demoConfig.batchB.reference,expectedEvidenceRevision:artifact?.evidence_revision,channel:identity?'identity_secure_task':'official_site_reference',intakeStatus:'released',text:draft,rationale:draft,key:type==='submit_response'?collabCtx.submissionKey:`COLLAB:${type}:${data.case.revision}:${item?.id||'request'}`});
  if(next!==data){versions.push(data);data=next;}
  if(type==='start_session')collabCtx.sessionId=data.contributorSessions.filter(x=>!collabCtx.requestId||x.request_id===collabCtx.requestId).at(-1)?.id||data.contributorSessions.at(-1)?.id;
  prepareCollabEdit();message=L('Saved in this synthetic session.','已保存到本合成会话。');persist();if(draw)render();return true;
 }catch(e){error=collaborationError(e);if(draw)render();return false;}
}
