function activityRecords(events){return `<p class="small muted">${L('Local demo activity, not a production audit ledger. Previous case versions are retained in this tab session.','本地演示活动，非生产审计账本；旧案件版本保留在当前标签页会话中。')}</p>${[...events].reverse().map(e=>`<article class="activity"><time>${new Date(e.occurred_at).toLocaleString(n.locale)}</time><p><strong>${actionLabel(e.event_type)}</strong> · ${roleLabel(e.actor_ref)}</p><p>${e.from_revision??'—'} → ${e.to_revision} · <span class="mono">${esc(e.correlation_id)}</span></p>${e.rationale?`<p>${esc(e.rationale)}</p>`:''}</article>`).join('')}`;}
