function actionLabel(type){if(batchLabels[type])return L(...batchLabels[type]);return L(({synthetic_fixture_authored:'Synthetic baseline authored',confirm_requirements:'Requirements confirmed',reuse_identity:'Evidence reuse assessed',send_residual_request:'Residual request recorded',receive_supplement:'Synthetic response received',assess_supplement:'Purpose assessment recorded',record_disposition:'Screening disposition recorded',refer:'Referred for review',request_evidence:'Information requested',pause:'Task paused'})[type]||type,({synthetic_fixture_authored:'已编制合成基线',confirm_requirements:'已确认演示要求',reuse_identity:'已评估证据复用',send_residual_request:'已记录剩余信息请求',receive_supplement:'已收到合成响应',assess_supplement:'已记录用途评估',record_disposition:'已记录筛查处置',refer:'已转交复核',request_evidence:'已请求信息',pause:'已暂停任务'})[type]||type);}
