 if(!isDSession())return `<main id="main">${returns}${specialistEntryHtml({locale:n.locale,canRestore:hasPreDArchive(),pending:dLoadPending,error})}${footer()}</main>`;
 const projection=dProjection();
 const body=n.dependency?specialistDependencyHtml({graph:n.dependency.graph,projection,locale:n.locale,focus:n.dGraph?.focus,playing:n.dGraph?.playing}):specialistConditionHtml({projection,domain:n.conditionDomain,role:n.role,locale:n.locale,agreementRevision:n.agreementRevision,liveAgreementRevision:n.liveAgreementRevision,rationale:dRationale,error,active:true});
 return `<main id="main">${returns}${caseStrip()}${message?`<div class="toast" role="status">${esc(message)}</div>`:''}${body}${footer()}</main>`;
