function product(){if(n.step==='condition')return specialistProduct();if(n.step==='collaboration')return collaborationWorkspace();if(isCProduct())return screeningProduct();const panel=({scope:()=>batch().panel(),parties:()=>batch().panel(),authority:()=>batch().panel(),tasks:()=>batch().panel(),requirements:requirementsPanel,evidence:()=>evidencePanel(false),gaps:gapsPanel,validation:()=>evidencePanel(true),screening:screeningPanel,clearance:clearancePanel,activity:activityPanel})[n.step]||screeningPanel;return `<main id="main"><div class="returnbar">${button('← '+L('Back to scenario','返回场景'),'return','scenario','ghost')}${button('↖ '+L('Back to journey','返回旅程'),'return','journey','ghost')}</div><div class="workspace-header"><div><span class="eyebrow">${L('PRODUCT PROTOTYPE / TARGET','产品原型 / TARGET')}</span><h1>${L('Case workspace','案件工作台')}</h1></div><label class="small muted">${L('Simulated role','模拟角色')} <select id="product-role">${!['ROLE-KYCOPS','ROLE-FINCRIME','ROLE-CASEMGR'].includes(n.role)?`<option value="${esc(n.role)}" selected>${esc(roleLabel(n.role))} · ${L('read-only','只读')}</option>`:''}${[['ROLE-KYCOPS','KYC Operations','KYC 运营'],['ROLE-FINCRIME','Financial Crime reviewer','金融犯罪复核人员'],['ROLE-CASEMGR','Case Manager · read-only','案件经理 · 只读']].map(([v,en,zh])=>`<option value="${v}" ${n.role===v?'selected':''}>${L(en,zh)}</option>`).join('')}</select></label></div>${caseStrip()}${isDSession()?specialistLegacyBannerHtml({locale:n.locale,canRestore:hasPreDArchive()}):''}${n.trigger!=='new-relationship'?`<div class="notice">${L('This trigger is not authored. Business actions are unavailable; return to the journey and select New relationship to operate the synthetic case.','此触发变体尚未编制，业务操作不可用。请返回旅程并选择新机构关系，再操作本合成案件。')}</div>`:''}${message?`<div class="toast" role="status">${esc(message)}</div>`:''}<div class="work-layout"><nav class="work-nav" aria-label="${L('Case workspace','案件工作台')}"><span class="eyebrow">${L('CASE WORK','案件工作')}</span>${['scope','parties','authority','tasks','requirements','evidence','gaps','validation','screening','clearance'].map((s,i)=>button(`<span class="mono">0${i+1}</span> &nbsp; ${stepTitle(s)}`,'step',s,n.step===s?'active':'')).join('')}<span class="eyebrow">${L('RECORD','记录')}</span>${button(stepTitle('activity'),'step','activity',n.step==='activity'?'active':'')}</nav><section class="work-panel"><h2>${stepTitle(n.step)} ${button('i','info','','info',`aria-label="${L('About this view','关于此视图')}" aria-expanded="${info}"`)}</h2>${info?`<div class="info-box">${L('All records are synthetic. Evidence is assessed for a subject and purpose. A task action changes only its defined objects; it never approves the whole client.','所有记录均为合成数据。证据按主体及用途评估；任务动作仅改变已定义对象，不批准整个客户。')}</div>`:''}${error?`<div class="error" role="alert">${esc(error)}</div>`:''}${panel()}</section>${workSide()}</div>${footer()}</main>`;}
function printView(){if(n.page==='product'&&n.step==='collaboration')return collaborationPrint();if(n.page==='product'&&isCProduct()&&data.demoConfig.batchC){const p=cProjection();return `<main id="main"><div class="no-print section-head">${button(L('Back to view','返回原视图'),'exit-print')}${button(L('Print / Save PDF','打印 / 保存 PDF'),'print','','primary')}</div><article class="print-sheet" data-print-scope="batch-c-product-${esc(cRole())}">${screeningWorkspaceHtml({projection:p,role:cRole(),step:n.step,locale:n.locale,print:true})}</article></main>`;}if(n.page==='studio'&&['SCN-POPULATION','SCN-MATCH','SCN-EDD'].includes(n.scenario)){const s=byId(n.scenario),p=data.demoConfig.batchC?cProjection():{},step=sceneStep(s.id);return `<main id="main"><div class="no-print section-head">${button(L('Back to view','返回原视图'),'exit-print')}${button(L('Print / Save PDF','打印 / 保存 PDF'),'print','','primary')}</div><article class="print-sheet" data-print-scope="batch-c-selected-scene"><p class="eyebrow">${esc(data.case.id)} · ${esc(s.id)} · ${n.comparison==='current'?'Current':'Target'} · SRC-016</p><h1>${T(s.title)}</h1><div class="print-meta">${L('Scope revision','范围版本')} ${data.scopes[0].revision} · ${L('Case revision','案件版本')} ${data.case.revision} · ${L('Synthetic internal review','合成内部评审')}</div><p>${T(n.comparison==='current'?s.current:s.target)}</p><p><strong>${L('Wait / input','等待 / 输入')}:</strong> ${T(s.wait)}</p><p><strong>${L('Human boundary','人工边界')}:</strong> ${T(s.human)}</p><p><strong>${L('Expected local result','预期本项结果')}:</strong> ${T(s.output)}</p>${data.demoConfig.batchC?screeningWorkspaceHtml({projection:p,role:cRole(),step,locale:n.locale,print:true}):`<div class="notice">${L('No Batch C business state has been opened; this is the authored static scene only.','尚未打开 Batch C 业务状态；此处仅为编制的静态场景。')}</div>`}${screeningSceneHtml({scene:s.id,locale:n.locale,mode:n.comparison==='current'?'Current':'Target',projection:p,print:true})}</article></main>`;}return `<main id="main"><div class="no-print section-head"><h2>${L('Print preview','打印预览')}</h2><div class="controls">${button(L('Back to view','返回原视图'),'exit-print')}${button(L('Print / Save PDF','打印 / 保存 PDF'),'print','','primary')}</div></div><article class="print-sheet" data-print-scope="round-a-all"><p class="eyebrow">CLEAR TO TRADE / ROUND A</p><h1>${L('Journey & first vertical slice','旅程与首个纵向切片')}</h1><div class="print-meta">${L('Internal review · synthetic data · not bank-approved policy','内部评审 · 合成数据 · 非银行已批准政策')}<br>DEMO-CTT-001 · ${n.locale} · ${L('Case revision','案件版本')} ${data.case.revision} · IA v0.4 / D2 v0.1</div><p>${L('Five reading stages:','五个阅读阶段：')} ${stages.map(s=>`${s[0]} ${L(s[1],s[2])}`).join(' / ')}</p><p>${L('Both Current and Target are printed for all authored scenarios, including content outside the screen viewport. Remaining scenarios are listed as structural scope.','打印全部已编制场景的 Current 与 Target，包含屏幕之外的内容；其余场景列为结构范围。')}</p>${data.demoConfig.batchA?batch().print():''}${scenes.map((s,i)=>`<section class="print-scene"><span class="mono">${String(i+1).padStart(2,'0')} · ${s.id} · ${s.stage} · ${s.process}</span><h2>${T(s.title)}</h2><div class="print-columns"><div><h3>Current</h3><p>${T(s.current)}</p></div><div><h3>Target</h3><p>${T(s.target)}</p></div></div><p><strong>${L('Wait / input','等待 / 输入')}:</strong> ${T(s.wait)}</p><p><strong>${L('Human boundary','人工边界')}:</strong> ${T(s.human)}</p><p><strong>${L('Expected result','预期结果')}:</strong> ${T(s.output)}</p><p class="small">SRC-007 · ${s.process} / SRC-010 §6 · ${L('Design hypothesis + synthetic record','设计假设 + 合成记录')} · ${s.journey?.join(', ')||s.id}</p></section>`).join('')}<section class="print-scene"><h2>${L('Additional journey structure','其余旅程结构')}</h2>${skeleton.map(x=>`<p><span class="mono">${x[0]} / ${x[4]}</span> — ${L(x[2],x[3])} · ${L('Structural scope','结构范围')}</p>`).join('')}</section><section class="print-scene"><h2>${L('Readiness proof — not ready','就绪状态证明 — 尚未就绪')}</h2>${data.clearanceConditions.map(c=>`<p><strong>${domainLabel(c)} — ${label(c.status)}</strong> · ${roleLabel(c.owner_role)}<br>${conditionReason(c)}</p>`).join('')}<p>${L('Authority unconfirmed. Publication not requested. No transaction is executed.','最终权限未确认，未请求发布，不执行交易。')}</p></section>${['current','target','screening'].map(k=>`<section class="print-diagram"><h2>${k==='screening'?L('Screening collaboration','筛查协作'):k==='current'?'Current':'Target'}</h2>${diagram(k)}</section>`).join('')}<section class="print-scene"><h2>${L('Open validation questions','待验证问题')}</h2><p>${L('Validate source permissions, requirement applicability, evidence sufficiency, human authority, EDD rationale and final QA/publication mandates. No client KPI, policy threshold or production integration is assumed.','需验证来源许可、要求适用性、证据充分性、人工权限、EDD 理由及最终 QA / 发布职责。未假设客户 KPI、政策阈值或生产集成。')}</p></section></article></main>`;}
function render(){
 const generation=++renderGeneration;
 if(modal.open&&renderedDialogKey)dialogScroll[renderedDialogKey]=modal.scrollTop;
 mediaHost.stop();
 const previous=captureGlass(),active=document.activeElement;
 const focus=active?.matches('button,select,input,textarea')?{id:active.id,action:active.dataset.action,value:active.dataset.value,dialog:active.closest('dialog')?.id}:null;
 const modalWasOpen=modal.open,modalPosition=modal.scrollTop;
 document.documentElement.lang=n.locale;app.innerHTML=header()+(n.mode==='print'?renderPrintView():n.page==='product'?product():studio());
 if(n.reference&&n.mode!=='print')showReference();else if(n.modal&&n.page==='studio'&&n.mode!=='print')(['SCN-CONFLICTS','SCN-CREDIT','SCN-LEGAL','SCN-READINESS'].includes(n.scenario)?showSpecialistScene():showScene());else{if(modal.open)modal.close();modal.innerHTML='';}
 enhanceSpecialistHost();refineLayout(n.locale);enhanceGlass(previous);bindBatchHelp();restoreCamera();bindDrag();persist();
 if(modal.open){const key=dialogScrollKey(n),position=dialogScroll[key]??(modalWasOpen&&renderedDialogKey===key?modalPosition:0);modal.scrollTop=position;const restoredTop=modal.scrollTop,scene=n.scenario;
  const slot=modal.querySelector('[data-media-scene]');if(slot)mediaHost.mount(slot,{scene,locale:n.locale,comparison:n.comparison}).then(()=>{if(generation!==renderGeneration||!slot.isConnected||!modal.open||n.scenario!==scene||modal.querySelector('[data-media-scene]')!==slot)return;const untouched=modal.scrollTop===restoredTop;if(untouched)modal.scrollTop=position;if(mediaPreviewPending){mediaPreviewPending=false;if(untouched){const panel=slot.closest('.mainline-media'),head=modal.querySelector('.modal-head');modal.scrollTop+=panel.getBoundingClientRect().top-head.getBoundingClientRect().bottom-12;}}});
  renderedDialogKey=key;renderedScene=n.reference?null:scene;
 }else{renderedScene=null;renderedDialogKey=null;}
 if(focus&&(!modal.open||focus.dialog==='scenario-dialog')&&!guard.open){const root=focus.dialog?document.getElementById(focus.dialog):app;
  const target=focus.id?document.getElementById(focus.id):[...root.querySelectorAll('button')].find(b=>b.dataset.action===focus.action&&b.dataset.value===focus.value);
  target?.focus({preventScroll:true});
 }
}
function bindDrag(){const box=document.querySelector('.journey-scroll');if(!box)return;let start=null;box.addEventListener('pointerdown',e=>{if(e.target.closest('button,a,input,select'))return;start={x:e.clientX,left:box.scrollLeft};box.setPointerCapture(e.pointerId);box.classList.add('dragging')});box.addEventListener('pointermove',e=>{if(start)box.scrollLeft=start.left-(e.clientX-start.x)});const end=()=>{start=null;box.classList.remove('dragging');camera();};box.addEventListener('pointerup',end);box.addEventListener('pointercancel',end);box.addEventListener('scroll',()=>{camera();const c=document.querySelector('#camera-status');if(c)c.textContent=n.stage;},{passive:true});}
function translatedError(e){const m=e.message;return n.locale!=='zh-CN'?m:/rationale/i.test(m)?'请填写支持该操作的理由。':/authority/i.test(m)?'当前角色未配置此操作的演示权限。':/requirements/i.test(m)?'请先确认演示要求。':/existing evidence/i.test(m)?'请求剩余缺口前，请先复核已有证据。':/received/i.test(m)?'尚未收到补充证据，请先记录请求并载入合成响应。':/revision/i.test(m)?'输入版本已变化，请复核当前输入后重新提交。':/evidence/i.test(m)?'需要充分且与用途关联的证据，请先完成证据复核。':/request/i.test(m)?'请先记录剩余信息请求。':/already/i.test(m)?'该处置已记录，本切片不开放重复处置。':'该操作当前不可执行，请检查输入和权限。';}
