function submit(type){try{const before=data;const next=act(data,{type,role:n.role,rationale:draft,expectedRevision:data.case.revision,key:`${type}:${data.case.revision}`,at:new Date().toISOString()});if(next!==data){versions.push(before);data=next;}drafts[n.step]='';draft='';dirty=false;error='';message=`${actionLabel(type)}. ${L('Overall case: not ready.','整体案件：尚未就绪。')}`;persist();render();}catch(e){error=translatedError(e);render();}}
function submitC(value,draw=true){
 try{
  if(!data.demoConfig.batchC)throw Object.assign(Error('C_CONTEXT_REQUIRED'),{code:'C_CONTEXT_REQUIRED'});
  if(!cEdit)prepareCEdit();const role=cRole(),type=value.startsWith('assess_identity_')?'assess_identity':value;
  const extra={};if(type==='receive_result'){extra.runId=data.screeningRuns.at(-1)?.id;extra.outcome=cOutcome;}if(type==='save_review_draft')extra.text=cRationale;if(type==='request_identity')extra.gap=cRationale;if(type==='assess_identity'){extra.evidenceId=data.evidence.filter(x=>x.request_item_refs?.includes(C_IDS.identityItem)).at(-1)?.id;extra.sufficiency=value.endsWith('insufficient')?'insufficient':'unknown';}if(type==='resume_branch')extra.branchId=data.workItems.find(x=>x.branch_type==='information_gap')?.id;
  const signature=JSON.stringify([type,role,cRationale,extra,cEdit?.revision,cEdit?.scopeRevision,cEdit?.inputRevisions]);
  let command;if(lastCCommand&&lastCCommand.signature===signature&&Date.now()-lastCCommand.at<1200)command=lastCCommand.command;else command={type,role,expectedRevision:cEdit.revision,expectedScopeRevision:cEdit.scopeRevision,expectedInputRevisions:structuredClone(cEdit.inputRevisions),key:crypto.randomUUID(),rationale:cRationale,at:new Date().toISOString(),...extra};
  const before=data,next=screeningAction(data,command);lastCCommand={signature,command,at:Date.now()};if(next!==data){versions.push(before);data=next;}
  cDirty=false;error='';message=L('Screening action recorded. Overall case remains Not ready.','筛查操作已记录；整体案件仍为尚未就绪。');prepareCEdit();persist();if(draw)render();return true;
 }catch(e){error=screeningErrorText(e);if(draw)render();return false;}
}
