function screeningComparison(received){
 const registry=obj('evidence','evidence','registry').content_attributes||{};
 const supplement=received?(obj('evidence','evidence','supplement').content_attributes||{}):{};
 const provider=data.screeningFindings[0].provider_attributes||{};
 const rows=[['legal_name',L('Legal name','法定名称'),registry.legal_name,provider.legal_name,L('Similar name · review','名称相似 · 需复核')],['registration_reference',L('Registration reference','登记引用'),supplement.registration_reference,provider.registration_reference,received?L('Different demo references','演示引用不同'):L('Unknown until received','收到资料前未知')],['incorporation_jurisdiction',L('Incorporation context','注册背景'),registry.incorporation_jurisdiction,provider.incorporation_jurisdiction,L('Compare with source','结合来源核对')],['entity_type',L('Entity type','主体类型'),supplement.entity_type,provider.entity_type,received?L('Same demo type','相同演示类型'):L('Not yet evidenced','尚无支持证据')]];
 const display=value=>value==='synthetic_corporation'?L('Corporation · synthetic','公司 · 合成'):esc(value);
 return `<table class="compare-table"><thead><tr><th>${L('Attribute','属性')}</th><th>${L('Subject','被筛查主体')}</th><th>${L('Provider record','来源记录')}</th><th>${L('Assessment','对照')}</th></tr></thead><tbody>${rows.map(([key,name,a,b,result])=>`<tr><td>${name}</td><td>${a?display(a):L('Not provided','尚未提供')}</td><td>${b?display(b):L('Unknown','未知')}</td><td>${result}</td></tr>`).join('')}</tbody></table>`;
}
